import { useState } from "react";

import { Button, Field, Modal } from "@/components/ui";
import { useAddSignal } from "../api";
import { familyLabel, SIGNAL_FORM, SIGNAL_HELP, SIGNAL_KINDS, signalBody, signalReady, type SignalFields, type SignalKindValue } from "../model/writes";
import styles from "../News.module.css";

type Change = { target: { value: string } };

/** "Add an early signal": a dated, sourced precursor signal for one story's backcast (never generated by a model). As
 *  before, the form stays mounted with its card, so it keeps what was typed while the page is open; a success closes it. */
export function SignalForm({ open, onClose, eventId, families }: { open: boolean; onClose: () => void; eventId: string; families: string[] }) {
  const [f, setF] = useState<SignalFields>(SIGNAL_FORM);
  const save = useAddSignal();
  const set = (k: Exclude<keyof SignalFields, "kind">) => (e: Change) => setF({ ...f, [k]: e.target.value });
  return (
    <Modal
      open={open}
      onClose={onClose}
      title="Add an early signal"
      footer={
        <Button
          variant="primary"
          busy={save.isPending}
          disabled={!signalReady(f)}
          onClick={() => save.mutate(signalBody(f, eventId), { onSuccess: onClose })}
          data-testid="news-signal-save"
        >
          Add
        </Button>
      }
    >
      <p className={styles.faint}>{SIGNAL_HELP}</p>
      <Field label="Date (YYYY, YYYY-MM or YYYY-MM-DD)">
        <input value={f.date} onChange={set("date")} placeholder="2021-06" />
      </Field>
      <Field label="What was visible">
        <input value={f.text} onChange={set("text")} />
      </Field>
      <Field label="Source URL">
        <input value={f.url} onChange={set("url")} placeholder="https://…" />
      </Field>
      <Field label="Signal family">
        <select value={f.family} onChange={set("family")}>
          {families.map((x) => (
            <option key={x} value={x}>
              {familyLabel(x)}
            </option>
          ))}
        </select>
      </Field>
      <Field label="Knowable at the time?">
        <select value={f.kind} onChange={(e) => setF({ ...f, kind: e.target.value as SignalKindValue })}>
          {SIGNAL_KINDS.map((k) => (
            <option key={k.value} value={k.value}>
              {k.label}
            </option>
          ))}
        </select>
      </Field>
    </Modal>
  );
}
